package com.campusconnect.attendance; import com.campusconnect.course.Course; import com.campusconnect.user.User; import jakarta.persistence.*; import java.time.LocalDate; import java.time.Instant;
@Entity @Table(name="attendance_records",uniqueConstraints=@UniqueConstraint(columnNames={"course_id","student_id","attendance_date"})) public class AttendanceRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Course course; @ManyToOne(optional=false) @JoinColumn(name="student_id") private User student; @ManyToOne(optional=false) @JoinColumn(name="marked_by_id") private User markedBy; @Column(name="attendance_date",nullable=false) private LocalDate attendanceDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=12) private Status status; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); public enum Status{PRESENT,ABSENT,LATE} protected AttendanceRecord(){} public AttendanceRecord(Course c,User s,User m,LocalDate d,Status st){course=c;student=s;markedBy=m;attendanceDate=d;status=st;} public Long getId(){return id;} public Course getCourse(){return course;} public User getStudent(){return student;} public LocalDate getAttendanceDate(){return attendanceDate;} public Status getStatus(){return status;} public void setStatus(Status s){status=s;} }
